"""Original board artwork and browser session bridge, with no external scripts."""
from pathlib import Path
import tempfile
import streamlit.components.v1 as components

HTML = r'''<!doctype html><html><head><meta charset="utf-8"><style>
*{box-sizing:border-box}html,body{margin:0;font-family:Arial,sans-serif;color:#203d35;background:transparent}#wrap{max-width:100%;margin:auto}#board{position:relative;width:100%;aspect-ratio:1;background:#e6eee1;border:3px solid #233f36;border-radius:8px;box-shadow:0 10px 32px #163b271a;overflow:hidden}.grid{position:absolute;inset:0;display:grid;grid-template-columns:1.45fr repeat(9,1fr) 1.45fr;grid-template-rows:1.45fr repeat(9,1fr) 1.45fr;gap:1px;background:#38594c}.square{position:relative;background:#faf7eb;overflow:hidden;border:0;padding:3px 2px;cursor:pointer;color:#233c35;font:600 clamp(6px,1.1vw,11px)/1.12 Arial;text-align:center;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:3px}.square:hover{background:#fff4d2;z-index:3;box-shadow:inset 0 0 0 2px #c69c49}.strip{height:14%;width:100%;position:absolute;left:0;top:0}.square[data-side=bottom] .strip{top:0}.square[data-side=top] .strip{bottom:0;top:auto}.square[data-side=left] .strip{height:100%;width:15%;left:auto;right:0}.square[data-side=right] .strip{height:100%;width:15%;left:0}.square[data-side=left]{padding-right:16%}.square[data-side=right]{padding-left:16%}.square[data-side=bottom]{padding-top:14%}.square[data-side=top]{padding-bottom:14%}.name{max-width:100%;overflow-wrap:anywhere}.price{font-weight:400;font-size:.95em}.icon{font-size:clamp(13px,2.3vw,26px)}.owner{width:8px;height:8px;border-radius:50%;position:absolute;right:3px;bottom:3px;border:1px solid white}.buildings{position:absolute;left:2px;top:0;color:#fff;font-size:10px;letter-spacing:1px;z-index:2;text-shadow:0 1px 1px #000}.mortgaged{opacity:.55}.center{grid-area:2/2/11/11;background:radial-gradient(ellipse at 50% 35%,#f1f4e6,#d7e5d6);position:relative;display:flex;align-items:center;justify-content:center;text-align:center;overflow:hidden}.center:before{content:"";position:absolute;inset:22px;border:1px solid #8fab9570;border-radius:50%}.center-inner{position:relative;z-index:1;width:90%}.eyebrow{font-size:clamp(8px,1.2vw,13px);letter-spacing:4px;text-transform:uppercase;color:#5d7867;margin-bottom:12px}.brand{font-family:Georgia,serif;font-weight:bold;font-size:clamp(26px,5.6vw,70px);letter-spacing:-2px;line-height:.9}.club{font-size:clamp(9px,1.5vw,18px);letter-spacing:5px;margin:12px auto 20px;padding:8px 12px;background:#b84b3d;color:#fff7e7;display:table;transform:rotate(-3deg)}.sub{font:italic clamp(11px,1.5vw,17px) Georgia,serif;color:#627864}.deckrow{display:flex;justify-content:space-around;gap:20px;margin:24px 16px}.deck{border:1px solid #bd9975;padding:12px 24px;border-radius:5px;box-shadow:3px 3px 0 #c8b196;font-family:Georgia,serif;background:#eecb8e;transform:rotate(-9deg);font-size:clamp(11px,1.8vw,20px)}.deck.chest{background:#b9d9d6;border-color:#729a97;box-shadow:3px 3px 0 #9bbdbb;transform:rotate(9deg)}.deck strong{display:block;font-size:32px;margin:6px}.dice{display:flex;justify-content:center;gap:12px;margin:14px}.die{display:grid;place-items:center;width:53px;height:53px;border-radius:11px;background:#fff9ed;border:1px solid #d0c5ae;box-shadow:0 4px 0 #c5bba6;font-size:46px;line-height:1;color:#354f45}.rolling{animation:roll .65s ease}.turn{font-size:clamp(12px,1.7vw,20px);font-weight:600;margin:12px}.supply{font-size:11px;color:#657c6c}.token{position:absolute;width:clamp(15px,2.8vw,28px);height:clamp(15px,2.8vw,28px);display:grid;place-items:center;font-size:clamp(11px,2vw,20px);border:2px solid white;border-radius:50%;z-index:5;box-shadow:0 2px 5px #0004;transition:left .18s linear,top .18s linear;pointer-events:none}.token.active{outline:2px solid #e8bf6a}.winner .brand{animation:win 2s infinite}.winner:after{content:"✦ ✧ ✦ ✧ ✦";position:absolute;top:20%;color:#c49a38;letter-spacing:22px;font-size:35px;animation:win 2s infinite}.foot{margin:8px 0 0;text-align:center;font-size:10px;color:#6e8075}@keyframes roll{0%{transform:rotate(-30deg) translateY(-10px)}40%{transform:rotate(30deg) translateY(3px)}70%{transform:rotate(-15deg)}100%{transform:none}}@keyframes win{50%{filter:brightness(1.2);transform:scale(1.03)}}@media(max-width:550px){.deckrow{margin:14px 8px;gap:8px}.deck{padding:7px 12px}.deck strong{font-size:20px}.die{width:36px;height:36px;font-size:31px}.brand{letter-spacing:-1px}.club{letter-spacing:2px}.center:before{inset:10px}.foot{font-size:8px}}
</style></head><body><div id="wrap"></div><script>
const post=(type,more={})=>parent.postMessage({isStreamlitMessage:true,type,...more},'*');
const send=value=>post('streamlit:setComponentValue',{value,dataType:'json'});
const el=(tag,cls,text)=>{let n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n};
let lastRoll=null,lastRoom=null,booted=false,tokenNodes={},args={},selected=null;
const faces=['','⚀','⚁','⚂','⚃','⚄','⚅'];
function position(i){if(i<=10)return [10-i,10];if(i<=20)return [0,20-i];if(i<=30)return [i-20,0];return [10,i-30]}
function side(i){return i<=10?'bottom':i<=20?'left':i<=30?'top':'right'}
function cell(i){return document.querySelector('[data-id="'+i+'"]')}
function height(){let wrap=document.getElementById('wrap');post('streamlit:setFrameHeight',{height:wrap.offsetHeight+(args.state?10:0)})}
function build(){let wrap=document.getElementById('wrap');wrap.replaceChildren();let board=el('div');board.id='board';wrap.append(board);let grid=el('div','grid');board.append(grid);args.board.forEach(b=>{let n=el('button','square');let [x,y]=position(b.id);n.style.gridArea=`${y+1}/${x+1}/${y+2}/${x+2}`;n.dataset.id=b.id;n.dataset.side=side(b.id);n.setAttribute('aria-label',b.name);n.title=b.name;n.onclick=()=>send({type:'select',id:b.id,nonce:crypto.randomUUID()});if(b.group){let stripe=el('div','strip');stripe.style.background=args.colors[b.group];n.append(stripe)}else{n.append(el('div','icon',{go:'➜',jail:'▥',gotojail:'↪',parking:'☕',station:'🚂',utility:b.id===12?'💡':'💧',chance:'?',chest:'▣',tax:'£'}[b.kind]||''))}n.append(el('div','name',b.name));if(b.price)n.append(el('div','price','£'+b.price));n.append(el('div','buildings'),el('span','owner'));grid.append(n)});let center=el('div','center');center.innerHTML='<div class="center-inner"><div class="eyebrow">THE CLASSIC LONDON TABLE</div><div class="brand">LONDON</div><div class="club">PROPERTY CLUB</div><div class="sub">A little luck. A lot of ambition.</div><div class="deckrow"><div class="deck chest">COMMUNITY<strong>▣</strong>CHEST</div><div class="deck">CHANCE<strong>?</strong>FORTUNE AWAITS</div></div><div class="dice"><div class="die" id="d1"></div><div class="die" id="d2"></div></div><div class="turn" id="turn"></div><div class="supply" id="supply"></div></div>';grid.append(center);wrap.append(el('div','foot','Click any space to inspect it · Original artwork · Unofficial fan project'));tokenNodes={};}
function moveToken(n,i,offset){let c=cell(i),b=document.getElementById('board');if(!c)return;let r=c.getBoundingClientRect(),br=b.getBoundingClientRect();n.style.left=(r.left-br.left+r.width*.22+(offset%3)*r.width*.23)+'px';n.style.top=(r.top-br.top+r.height*.56+Math.floor(offset/3)*r.height*.19)+'px'}
function render(){if(!args.state){document.getElementById('wrap').replaceChildren();height();return}if(!document.getElementById('board')||lastRoom!==args.room){build();lastRoom=args.room}let s=args.state;let board=document.getElementById('board');document.querySelector('.center').classList.toggle('winner',s.status==='finished');for(let b of args.board){let n=cell(b.id),d=s.deeds[String(b.id)],owner=n.querySelector('.owner');if(d){n.classList.toggle('mortgaged',d.mortgaged);owner.style.display=d.owner?'block':'none';if(d.owner)owner.style.background=args.player_colors[s.order.indexOf(d.owner)];n.querySelector('.buildings').textContent=d.level===5?'▣':('⌂'.repeat(d.level))}else owner.style.display='none'}let offsets={};s.order.forEach((pid,index)=>{let p=s.players[pid];if(p.bankrupt){tokenNodes[pid]?.remove();delete tokenNodes[pid];return}let n=tokenNodes[pid];if(!n){n=el('div','token',p.token);n.style.background=args.player_colors[index];board.append(n);tokenNodes[pid]=n}n.classList.toggle('active',pid===s.order[s.turn]);let offset=offsets[p.pos]||0;offsets[p.pos]=offset+1;moveToken(n,p.pos,offset)});let isNew=lastRoll!==null&&lastRoll!==s.roll_id;[1,2].forEach((i)=>{let d=document.getElementById('d'+i);d.textContent=faces[s.dice[i-1]];if(isNew){d.classList.remove('rolling');void d.offsetWidth;d.classList.add('rolling')}});lastRoll=s.roll_id;let p=s.players[s.order[s.turn]];document.getElementById('turn').textContent=s.status==='lobby'?'Your next game night starts here.':s.status==='finished'?s.players[s.winner].name+' wins!':p.name+' · '+(p.jail?'In jail':s.stage==='roll'?'Ready to roll':'Finish your turn');document.getElementById('supply').textContent=s.houses+' houses · '+s.hotels+' hotels in the bank';height()}
window.addEventListener('message',e=>{if(e.data.type!=='streamlit:render')return;args=e.data.args||{};try{if(args.credentials){localStorage.setItem('london-session-'+args.credentials.code,JSON.stringify(args.credentials));localStorage.setItem('london-last-room',args.credentials.code)}if(args.clear){localStorage.removeItem('london-last-room')}}catch{}if(!booted){booted=true;let saved=null;try{let code=args.invite||localStorage.getItem('london-last-room');saved=JSON.parse(localStorage.getItem('london-session-'+code)||'null')}catch{}send({type:'restore',credentials:saved,nonce:crypto.randomUUID()})}render()});new ResizeObserver(()=>{if(args.state)render()}).observe(document.body);post('streamlit:componentReady',{apiVersion:1});
</script></body></html>'''


def component():
    directory=Path(tempfile.gettempdir())/"london-monopoly-component-v1"
    directory.mkdir(exist_ok=True)
    target=directory/"index.html"
    if not target.exists() or target.read_text(encoding="utf-8")!=HTML:
        target.write_text(HTML,encoding="utf-8")
    return components.declare_component("london_table",path=str(directory))
